"""Synthetic FAT12, FAT16, and FAT32 filesystem image generator for forensic testing."""

import hashlib
import struct
from dataclasses import dataclass, field
from pathlib import Path

from recoverx.domain.enums import FileSystemType
from recoverx.filesystems.fat.entry import fat_lfn_checksum


@dataclass(slots=True)
class ExpectedFatFile:
    """Expected file metadata recorded in synthetic FAT image manifest."""

    filename: str
    relative_path: str
    content: bytes
    sha256_hash: str
    is_deleted: bool
    is_overwritten: bool
    first_cluster: int
    size_bytes: int


@dataclass(slots=True)
class SyntheticFatManifest:
    """Manifest describing files and filesystem geometry generated by SyntheticFatBuilder."""

    image_path: Path
    filesystem_type: FileSystemType
    total_size_bytes: int
    cluster_size_bytes: int
    files: list[ExpectedFatFile] = field(default_factory=list)

    def get_file(self, filename: str) -> ExpectedFatFile | None:
        """Find an expected file by filename."""
        for f in self.files:
            if f.filename == filename:
                return f
        return None


class SyntheticFatBuilder:
    """Constructs mathematically valid FAT12, FAT16, or FAT32 disk images with known files."""

    def __init__(
        self,
        fs_type: FileSystemType = FileSystemType.FAT32,
        volume_label: str = "TEST_FAT",
    ) -> None:
        self.fs_type = fs_type
        self.volume_label = volume_label
        self._files_to_add: list[
            tuple[str, str, bytes, bool, bool]
        ] = []  # (name, subpath, content, is_deleted, is_overwritten)

    def add_file(
        self,
        filename: str,
        content: bytes,
        subpath: str = "",
        is_deleted: bool = False,
        is_overwritten: bool = False,
    ) -> "SyntheticFatBuilder":
        """Queue a file for inclusion in the generated image."""
        self._files_to_add.append((filename, subpath, content, is_deleted, is_overwritten))
        return self

    def build(self, output_path: Path) -> SyntheticFatManifest:
        """Assemble the complete disk image and return its manifest."""
        output_path.parent.mkdir(parents=True, exist_ok=True)

        bytes_per_sec = 512
        if self.fs_type == FileSystemType.FAT12:
            total_sectors = 2880  # 1.44 MB standard floppy
            sec_per_clus = 1
            rsvd_sec = 1
            num_fats = 2
            root_entries = 224
            fat_sz_16 = 9
            fat_sz_32 = 0
            root_clus = 0
            bk_boot_sec = 0
        elif self.fs_type == FileSystemType.FAT16:
            total_sectors = 32768  # 16 MB
            sec_per_clus = 4  # 2048 byte clusters
            rsvd_sec = 1
            num_fats = 2
            root_entries = 512
            fat_sz_16 = 32
            fat_sz_32 = 0
            root_clus = 0
            bk_boot_sec = 0
        else:  # FAT32
            total_sectors = 131072  # 64 MB
            sec_per_clus = 1  # 512 byte clusters -> 128992 clusters (qualifies as FAT32 >= 65525)
            rsvd_sec = 32
            num_fats = 2
            root_entries = 0
            fat_sz_16 = 0
            fat_sz_32 = 1024
            root_clus = 2
            bk_boot_sec = 6

        root_dir_sectors = ((root_entries * 32) + (bytes_per_sec - 1)) // bytes_per_sec
        fat_sz = fat_sz_16 if fat_sz_16 != 0 else fat_sz_32
        first_data_sec = rsvd_sec + (num_fats * fat_sz) + root_dir_sectors
        cluster_size = bytes_per_sec * sec_per_clus
        total_size = total_sectors * bytes_per_sec

        image = bytearray(total_size)

        # 1. Build Boot Sector (Sector 0)
        boot_sector = bytearray(512)
        boot_sector[0:3] = b"\xeb\x3c\x90"
        boot_sector[3:11] = b"RECOVERX"
        struct.pack_into("<H", boot_sector, 11, bytes_per_sec)
        boot_sector[13] = sec_per_clus
        struct.pack_into("<H", boot_sector, 14, rsvd_sec)
        boot_sector[16] = num_fats
        struct.pack_into("<H", boot_sector, 17, root_entries)
        if total_sectors < 65536:
            struct.pack_into("<H", boot_sector, 19, total_sectors)
        else:
            struct.pack_into("<H", boot_sector, 19, 0)
            struct.pack_into("<I", boot_sector, 32, total_sectors)
        boot_sector[21] = 0xF8  # Media: fixed disk / flash drive
        struct.pack_into("<H", boot_sector, 22, fat_sz_16)

        if self.fs_type in (FileSystemType.FAT12, FileSystemType.FAT16):
            boot_sector[36] = 0x80  # Drive num
            boot_sector[38] = 0x29  # Boot sig
            struct.pack_into("<I", boot_sector, 39, 0x12345678)
            boot_sector[43:54] = self.volume_label.ljust(11)[:11].encode("latin-1")
            boot_sector[54:62] = (
                b"FAT12   " if self.fs_type == FileSystemType.FAT12 else b"FAT16   "
            )
        else:
            struct.pack_into("<I", boot_sector, 36, fat_sz_32)
            struct.pack_into("<H", boot_sector, 40, 0)  # ExtFlags
            struct.pack_into("<H", boot_sector, 42, 0)  # FSVer
            struct.pack_into("<I", boot_sector, 44, root_clus)
            struct.pack_into("<H", boot_sector, 48, 1)  # FSInfo
            struct.pack_into("<H", boot_sector, 50, bk_boot_sec)
            boot_sector[64] = 0x80
            boot_sector[66] = 0x29
            struct.pack_into("<I", boot_sector, 67, 0x12345678)
            boot_sector[71:82] = self.volume_label.ljust(11)[:11].encode("latin-1")
            boot_sector[82:90] = b"FAT32   "

        boot_sector[510:512] = b"\x55\xaa"
        image[0:512] = boot_sector

        # Backup boot sector for FAT32
        if self.fs_type == FileSystemType.FAT32 and bk_boot_sec > 0:
            bk_offset = bk_boot_sec * bytes_per_sec
            image[bk_offset : bk_offset + 512] = boot_sector

        # 2. Initialize FAT Tables
        fat1_offset = rsvd_sec * bytes_per_sec
        fat2_offset = (rsvd_sec + fat_sz) * bytes_per_sec
        fat_bytes = bytearray(fat_sz * bytes_per_sec)

        # Cluster 0 and 1 initial values
        if self.fs_type == FileSystemType.FAT12:
            self._set_fat_entry(fat_bytes, 0, 0x0FF8)
            self._set_fat_entry(fat_bytes, 1, 0x0FFF)
        elif self.fs_type == FileSystemType.FAT16:
            self._set_fat_entry(fat_bytes, 0, 0xFFF8)
            self._set_fat_entry(fat_bytes, 1, 0xFFFF)
        else:  # FAT32
            self._set_fat_entry(fat_bytes, 0, 0x0FFFFFF8)
            self._set_fat_entry(fat_bytes, 1, 0x0FFFFFFF)
            # Allocate root cluster 2
            self._set_fat_entry(fat_bytes, 2, 0x0FFFFFFF)

        # 3. Allocate and Write Files
        next_free_cluster = 3 if self.fs_type == FileSystemType.FAT32 else 2
        root_dir_entries: bytearray = bytearray()
        manifest_files: list[ExpectedFatFile] = []

        def get_cluster_byte_offset(c: int) -> int:
            return (first_data_sec + ((c - 2) * sec_per_clus)) * bytes_per_sec

        for filename, subpath, content, is_del, is_overwritten in self._files_to_add:
            content_size = len(content)
            clusters_needed = (
                (content_size + cluster_size - 1) // cluster_size if content_size > 0 else 0
            )

            file_first_cluster = next_free_cluster if clusters_needed > 0 else 0

            # Write content to data clusters
            if clusters_needed > 0:
                for idx in range(clusters_needed):
                    clus = file_first_cluster + idx
                    clus_off = get_cluster_byte_offset(clus)
                    chunk_start = idx * cluster_size
                    chunk = content[chunk_start : chunk_start + cluster_size]
                    image[clus_off : clus_off + len(chunk)] = chunk

                    # Update FAT chain
                    is_last_clus = idx == (clusters_needed - 1)
                    next_ptr = (
                        (
                            0x0FFFFFFF
                            if self.fs_type == FileSystemType.FAT32
                            else (0xFFFF if self.fs_type == FileSystemType.FAT16 else 0x0FFF)
                        )
                        if is_last_clus
                        else (clus + 1)
                    )

                    if not is_del:
                        # Active file: record chain in FAT table
                        self._set_fat_entry(fat_bytes, clus, next_ptr)
                    elif is_overwritten and idx == 0:
                        # Overwritten file: first cluster is allocated to another chain!
                        self._set_fat_entry(fat_bytes, clus, 0x00000004)
                    else:
                        # Deleted file: chain is cleared (0)
                        self._set_fat_entry(fat_bytes, clus, 0)

                next_free_cluster += clusters_needed

            # Generate Directory Entries (LFNs + 8.3 entry)
            dir_entries_bytes = self._create_dir_entries(
                filename=filename,
                first_cluster=file_first_cluster,
                file_size=content_size,
                is_deleted=is_del,
            )
            root_dir_entries.extend(dir_entries_bytes)

            manifest_files.append(
                ExpectedFatFile(
                    filename=filename,
                    relative_path=filename if not subpath else f"{subpath}/{filename}",
                    content=content,
                    sha256_hash=hashlib.sha256(content).hexdigest(),
                    is_deleted=is_del,
                    is_overwritten=is_overwritten,
                    first_cluster=file_first_cluster,
                    size_bytes=content_size,
                )
            )

        # Write root directory into image
        if self.fs_type == FileSystemType.FAT32:
            root_off = get_cluster_byte_offset(root_clus)
            image[root_off : root_off + len(root_dir_entries)] = root_dir_entries
        else:
            root_off = (rsvd_sec + (num_fats * fat_sz)) * bytes_per_sec
            image[root_off : root_off + len(root_dir_entries)] = root_dir_entries

        # Copy FAT tables into image
        image[fat1_offset : fat1_offset + len(fat_bytes)] = fat_bytes
        image[fat2_offset : fat2_offset + len(fat_bytes)] = fat_bytes

        # Write complete image to disk
        output_path.write_bytes(image)

        return SyntheticFatManifest(
            image_path=output_path,
            filesystem_type=self.fs_type,
            total_size_bytes=total_size,
            cluster_size_bytes=cluster_size,
            files=manifest_files,
        )

    def _set_fat_entry(self, fat_bytes: bytearray, cluster: int, value: int) -> None:
        """Set a cluster entry in the in-memory FAT table."""
        if self.fs_type == FileSystemType.FAT12:
            offset = (cluster * 3) // 2
            val16 = struct.unpack_from("<H", fat_bytes, offset)[0]
            if cluster % 2 == 0:
                val16 = (val16 & 0xF000) | (value & 0x0FFF)
            else:
                val16 = (val16 & 0x000F) | ((value & 0x0FFF) << 4)
            struct.pack_into("<H", fat_bytes, offset, val16)
        elif self.fs_type == FileSystemType.FAT16:
            offset = cluster * 2
            struct.pack_into("<H", fat_bytes, offset, value & 0xFFFF)
        else:  # FAT32
            offset = cluster * 4
            old_val = struct.unpack_from("<I", fat_bytes, offset)[0]
            new_val = (old_val & 0xF0000000) | (value & 0x0FFFFFFF)
            struct.pack_into("<I", fat_bytes, offset, new_val)

    def _create_dir_entries(
        self,
        filename: str,
        first_cluster: int,
        file_size: int,
        is_deleted: bool,
    ) -> bytearray:
        """Construct LFN entries and short directory entry for a file."""
        entries = bytearray()

        # Build 11-byte short name
        parts = filename.split(".", 1)
        base = parts[0].upper().replace(" ", "_")[:8].ljust(8)
        ext = parts[1].upper()[:3].ljust(3) if len(parts) > 1 else "   "
        short_11 = (base + ext).encode("latin-1")

        chksum = fat_lfn_checksum(short_11)

        # Build LFN parts (13 UTF-16 chars per part)
        lfn_slices: list[str] = []
        name_len = len(filename)
        for i in range(0, name_len, 13):
            lfn_slices.append(filename[i : i + 13])

        # LFN parts are stored on disk in REVERSE order
        total_parts = len(lfn_slices)
        for idx in reversed(range(total_parts)):
            seq = idx + 1
            is_last = idx == (total_parts - 1)
            chunk = lfn_slices[idx]

            chars = list(chunk)
            if len(chars) < 13:
                chars.append("\x00")
                while len(chars) < 13:
                    chars.append("\uffff")

            chars_part1 = "".join(chars[0:5]).encode("utf-16-le")
            chars_part2 = "".join(chars[5:11]).encode("utf-16-le")
            chars_part3 = "".join(chars[11:13]).encode("utf-16-le")

            lfn_entry = bytearray(32)
            ord_byte = 0xE5 if is_deleted else ((seq & 0x1F) | (0x40 if is_last else 0))
            lfn_entry[0] = ord_byte
            lfn_entry[1:11] = chars_part1
            lfn_entry[11] = 0x0F  # ATTR_LONG_NAME
            lfn_entry[12] = 0x00  # Type
            lfn_entry[13] = chksum
            lfn_entry[14:26] = chars_part2
            lfn_entry[26:28] = b"\x00\x00"
            lfn_entry[28:32] = chars_part3

            entries.extend(lfn_entry)

        # Build Short 8.3 Entry
        short_entry = bytearray(32)
        raw_name = bytearray(short_11)
        if is_deleted:
            raw_name[0] = 0xE5
        short_entry[0:11] = raw_name
        short_entry[11] = 0x20  # ATTR_ARCHIVE

        # First cluster HI/LO
        fst_hi = (first_cluster >> 16) & 0xFFFF
        fst_lo = first_cluster & 0xFFFF
        struct.pack_into("<H", short_entry, 20, fst_hi)
        struct.pack_into("<H", short_entry, 26, fst_lo)
        struct.pack_into("<I", short_entry, 28, file_size)

        entries.extend(short_entry)
        return entries
